// Progressive enhancement for the resource directory.
// The cards are plain HTML generated by scripts/build.py from data/workbooks.json, so the page
// works without JavaScript (roadmaps and workbooks are then simply shown one after the other).
// This file adds the Roadmaps / Workbooks toggle, search and subject filters once there are
// enough workbooks (data-search-from on the directory), and keeps the footer year current.
(function () {
  "use strict";

  function $all(sel, root) { return Array.prototype.slice.call((root || document).querySelectorAll(sel)); }

  function setupFilters(dir) {
    var cards = $all(".card[data-category]", dir);
    var threshold = parseInt(dir.getAttribute("data-search-from"), 10) || 6;
    if (cards.length < threshold) return;

    // Subjects in page order, labelled with the card badge text.
    var subjects = [];
    cards.forEach(function (c) {
      var id = c.getAttribute("data-category");
      if (!subjects.some(function (s) { return s.id === id; })) {
        var badge = c.querySelector(".badge");
        subjects.push({ id: id, label: badge ? badge.textContent : id });
      }
    });

    var controls = document.createElement("div");
    controls.className = "controls";
    controls.innerHTML =
      '<label class="search"><span class="visually-hidden">Search workbooks</span>' +
      '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="11" cy="11" r="7"/><path d="m20 20-3.5-3.5"/></svg>' +
      '<input type="search" placeholder="Search by topic or skill" autocomplete="off"></label>' +
      '<div class="chips" role="group" aria-label="Filter by subject"></div>';
    var chipBox = controls.querySelector(".chips");
    [{ id: "all", label: "All" }].concat(subjects).forEach(function (s) {
      var b = document.createElement("button");
      b.type = "button";
      b.className = "chip";
      b.textContent = s.label;
      b.setAttribute("data-cat", s.id);
      b.setAttribute("aria-pressed", String(s.id === "all"));
      chipBox.appendChild(b);
    });

    var empty = document.createElement("p");
    empty.className = "empty";
    empty.setAttribute("role", "status");
    empty.hidden = true;
    empty.textContent = "No workbooks match that search. Try a broader term like “data” or clear the filter.";

    dir.parentNode.insertBefore(controls, dir);
    dir.parentNode.insertBefore(empty, dir.nextSibling);

    var state = { query: "", category: "all" };

    function apply() {
      var terms = state.query ? state.query.split(/\s+/) : [];
      var shown = 0;
      cards.forEach(function (c) {
        var hay = c.getAttribute("data-search") || "";
        var ok = (state.category === "all" || c.getAttribute("data-category") === state.category) &&
          terms.every(function (t) { return hay.indexOf(t) !== -1; });
        c.hidden = !ok;
        if (ok) shown++;
      });
      $all("[data-category-section]", dir).forEach(function (sec) {
        sec.hidden = !$all(".card:not([hidden])", sec).length;
      });
      empty.hidden = shown > 0;
    }

    controls.querySelector("input").addEventListener("input", function (e) {
      state.query = e.target.value.trim().toLowerCase();
      apply();
    });
    chipBox.addEventListener("click", function (e) {
      var btn = e.target.closest("[data-cat]");
      if (!btn) return;
      state.category = btn.getAttribute("data-cat");
      $all("[data-cat]", chipBox).forEach(function (b) { b.setAttribute("aria-pressed", String(b === btn)); });
      apply();
    });
  }

  // Roadmaps / Workbooks toggle (WAI-ARIA tabs). #roadmaps and #workbooks links select a tab.
  function setupTabs(box) {
    var tabs = $all("[data-tab]", box);
    var panels = tabs.map(function (t) {
      return document.querySelector('[data-panel="' + t.getAttribute("data-tab") + '"]');
    });
    if (!tabs.length || panels.some(function (p) { return !p; })) return;

    box.setAttribute("role", "tablist");
    box.setAttribute("aria-label", "Resource type");
    tabs.forEach(function (t, i) {
      t.setAttribute("role", "tab");
      t.setAttribute("aria-controls", panels[i].id);
      panels[i].setAttribute("role", "tabpanel");
      panels[i].setAttribute("aria-labelledby", t.id);
      panels[i].classList.add("is-tabbed");
    });

    function select(i, focus) {
      tabs.forEach(function (t, j) {
        var on = i === j;
        t.setAttribute("aria-selected", String(on));
        t.tabIndex = on ? 0 : -1;
        panels[j].hidden = !on;
      });
      if (focus) tabs[i].focus();
    }
    function indexForHash() {
      var id = decodeURIComponent(location.hash.slice(1));
      for (var i = 0; i < panels.length; i++) if (panels[i].id === id) return i;
      return -1;
    }

    box.addEventListener("click", function (e) {
      var t = e.target.closest("[data-tab]");
      if (!t) return;
      var i = tabs.indexOf(t);
      select(i);
      if (history.replaceState) history.replaceState(null, "", "#" + panels[i].id);
    });
    box.addEventListener("keydown", function (e) {
      var i = tabs.indexOf(document.activeElement);
      if (i < 0) return;
      var next = { ArrowRight: i + 1, ArrowLeft: i - 1, Home: 0, End: tabs.length - 1 }[e.key];
      if (next === undefined) return;
      e.preventDefault();
      next = (next + tabs.length) % tabs.length;
      select(next, true);
      if (history.replaceState) history.replaceState(null, "", "#" + panels[next].id);
    });
    window.addEventListener("hashchange", function () {
      var i = indexForHash();
      if (i >= 0) select(i);
    });

    var start = indexForHash();
    select(start >= 0 ? start : 0);
    box.hidden = false;
  }

  document.addEventListener("DOMContentLoaded", function () {
    var year = document.querySelector("[data-year]");
    if (year) year.textContent = new Date().getFullYear();
    var tabs = document.querySelector("[data-tabs]");
    if (tabs) setupTabs(tabs);
    var dir = document.querySelector("[data-directory]");
    if (dir) setupFilters(dir);
  });
})();
